import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";

/**
 * Labeled on/off row shared by the canvas settings panels: a 44pt switch with
 * the label on the start side and the track on the end side (mirrored in RTL).
 */
export function SettingSwitch({label,on,onChange,disabled,styled,hint}:{
  label:string;on:boolean;onChange:(on:boolean)=>void;disabled:boolean;styled:boolean;hint?:string|undefined;
}){
  return <Pressable role="switch" aria-checked={on} accessibilityRole="switch" accessibilityState={{checked:on,disabled}}
    aria-label={label} accessibilityHint={hint} disabled={disabled} onPress={()=>onChange(!on)}
    {...{className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:44,flexDirection:"row",alignItems:"center",justifyContent:"space-between",gap:12,paddingHorizontal:4,opacity:disabled?0.5:1}}>
    <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{flexShrink:1}}>{label}</Text>
    <View pointerEvents="none" {...{className:joinClasses(styled&&"border",styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:40,height:24,borderRadius:12,padding:2,justifyContent:"center",alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:18,height:18,borderRadius:9}}/>
    </View>
  </Pressable>;
}

import {Text,TextInput,View,type ViewProps} from 'react-native';
import {Select} from '@/components/nyc-tron/ui/components/Select';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';
import {SettingSwitch} from '@/components/nyc-tron/ui/components/forge/canvas/SettingSwitch';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
import {validatePhotoTargets} from '@/components/nyc-tron/ui/components/forge/photo/photo-presets';
import {validatePhotoExport,validatePhotoExportProgress,type PhotoBatchExportSettings,type PhotoExportFormat,type PhotoExportProgress} from '@/components/nyc-tron/ui/components/forge/photo/photo-export';
export type {PhotoBatchExportSettings,PhotoExportFormat,PhotoExportProgress} from '@/components/nyc-tron/ui/components/forge/photo/photo-export';
export interface BatchExportPanelProps extends Omit<ViewProps,'children'> {
 readonly scope:string;readonly photoIds:readonly string[];readonly value:PhotoBatchExportSettings;readonly formats:readonly PhotoExportFormat[];
 readonly onChange:(settings:PhotoBatchExportSettings)=>void;readonly onExport:(photoIds:readonly string[],settings:PhotoBatchExportSettings,signal:AbortSignal)=>void|Promise<void>;
 readonly progress?:PhotoExportProgress|null;readonly disabled?:boolean;readonly unstyled?:boolean;
}
/** Configures a host's real batch encoder and reports only provider-supplied progress. */
export function BatchExportPanel({scope,photoIds,value,formats,onChange,onExport,progress=null,disabled=false,unstyled=false,...props}:BatchExportPanelProps){
 validatePhotoTargets(photoIds);validatePhotoExport(value,formats);if(progress!==null)validatePhotoExportProgress(progress);if(!scope.trim())throw new TypeError('Batch export requires a scope');
 const action=useOwnedAction(scope),locked=disabled||action.pending!==null,format=formats.find(format=>format.id===value.formatId)!;
 const set=(change:Partial<PhotoBatchExportSettings>)=>{if(locked)return;const next={...value,...change};validatePhotoExport(next,formats);onChange(next);};
 const watermark=(change:Partial<PhotoBatchExportSettings['watermark']>)=>set({watermark:{...value.watermark,...change}});
 return <View {...props} style={[{gap:8},props.style]}>
  <Select label="Photo export format" value={value.formatId} options={formats.map(format=>({value:format.id,label:format.label}))} disabled={locked} unstyled={unstyled} onValueChange={formatId=>set({formatId})}/>
  <Select label="Photo export sizing" value={value.sizing} options={[{value:'original',label:'Original size'},{value:'fit-long-edge',label:'Fit long edge'}]} disabled={locked} unstyled={unstyled} onValueChange={sizing=>set({sizing:sizing as PhotoBatchExportSettings['sizing']})}/>
  <UnitInput label="Export long edge pixels" value={value.longEdge} min={1} max={65536} precision={0} step={1} disabled={locked||value.sizing==='original'} unstyled={unstyled} onCommit={longEdge=>set({longEdge:Math.round(longEdge)})}/>
  <UnitInput label="Photo export quality" value={value.quality} min={1} max={100} step={1} disabled={locked||!format.supportsQuality} unstyled={unstyled} onCommit={quality=>set({quality})}/>
  <Select label="Photo metadata privacy" value={value.metadata} options={[{value:'strip-all',label:'Remove all metadata'},{value:'copyright-only',label:'Keep copyright only'},{value:'preserve-without-location',label:'Keep metadata, remove location'},{value:'preserve-all',label:'Keep all metadata, including location'}]} disabled={locked} unstyled={unstyled} onValueChange={metadata=>set({metadata:metadata as PhotoBatchExportSettings['metadata']})}/>
  <SettingSwitch label="Add text watermark" on={value.watermark.enabled} onChange={enabled=>watermark({enabled})} disabled={locked} styled={!unstyled}/>
  <TextInput accessibilityLabel="Photo watermark text" value={value.watermark.text} maxLength={256} editable={!locked&&value.watermark.enabled} aria-disabled={locked||!value.watermark.enabled} onChangeText={text=>watermark({text})} style={{minHeight:44,padding:8}} {...{className:joinClasses(!unstyled&&'text-text border border-border rounded-control')}}/>
  <UnitInput label="Watermark opacity" value={value.watermark.opacity} min={0} max={1} step={.05} disabled={locked||!value.watermark.enabled} unstyled={unstyled} onCommit={opacity=>watermark({opacity})}/>
  <UnitInput label="Watermark font pixels" value={value.watermark.fontSize} min={1} max={1024} step={1} disabled={locked||!value.watermark.enabled} unstyled={unstyled} onCommit={fontSize=>watermark({fontSize})}/>
  <Select label="Watermark position" value={value.watermark.position} options={['top-left','top-right','center','bottom-left','bottom-right'].map(value=>({value,label:value.replaceAll('-',' ')}))} disabled={locked||!value.watermark.enabled} unstyled={unstyled} onValueChange={position=>watermark({position:position as PhotoBatchExportSettings['watermark']['position']})}/>
  {progress?<Text accessibilityLiveRegion="polite" {...{className:joinClasses(!unstyled&&'text-text')}}>{`${progress.completed} exported; ${progress.failed} failed; ${progress.total} total`}</Text>:action.pending!==null?<Text {...{className:joinClasses(!unstyled&&'text-text-muted')}}>Export in progress; progress not reported</Text>:null}
  <Button title={`Export ${photoIds.length} photos`} disabled={locked||photoIds.length===0||value.watermark.enabled&&!value.watermark.text.trim()} unstyled={unstyled} onPress={()=>{if(!locked&&photoIds.length&&(!value.watermark.enabled||value.watermark.text.trim()))void action.run('export',signal=>onExport([...photoIds],{...value,watermark:{...value.watermark}},signal));}}/>
  {action.pending!==null?<Button title="Cancel photo export" unstyled={unstyled} onPress={action.cancel}/>:null}
  <ErrorMessage {...(action.error?{message:action.error}:{})} unstyled={unstyled}/>
 </View>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
